  nodes: GraphNode[];
  relationships: GraphEdge[];
  length: number;
}

TraversalConfig​
export interface TraversalConfig {
  startId: string;
  relationshipTypes?: string[];
  maxDepth: number;
  direction?: "OUTGOING" | "INCOMING" | "BOTH";
  filter?: string;
  filterParams?: Record<string, unknown>;
}

ShortestPathConfig​
export interface ShortestPathConfig {
  fromId: string;
  toId: string;
  maxHops: number;
  relationshipTypes?: string[];
  direction?: "OUTGOING" | "INCOMING" | "BOTH";
