  type:
    | "CREATE_NODE"
    | "UPDATE_NODE"
    | "DELETE_NODE"
    | "CREATE_EDGE"
    | "DELETE_EDGE";
  data:
    | GraphNode
    | GraphEdge
    | { id: string; properties?: Record<string, unknown> };
}

GraphJobReceipt​
export interface GraphJobReceipt { id: string; generation: string; identity: GraphIdentity; sourceRevision: number }

GraphApplyResult​
